SELECT c.is_active, CASE WHEN c.age >= 72 THEN 'high' WHEN c.age >= 35 THEN 'mid' ELSE 'low' END AS age_bucket, SORT_ARRAY(COLLECT_SET(s.status)) AS status_list FROM subscriptions s LEFT OUTER JOIN customers c ON s.customer_id = c.id WHERE s.monthly_fee BETWEEN 90 AND 140 GROUP BY c.is_active, CASE WHEN c.age >= 72 THEN 'high' WHEN c.age >= 35 THEN 'mid' ELSE 'low' END ORDER BY age_bucket;
